import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A 2-dimensional synthetic benchmark function combining a sigmoidal transformation, polynomial terms, and a product term to shape the landscape.
    It introduces non-linearity through the sigmoid and aims to control ELA features, particularly skewness and fitness-distance correlations.

    Formula:
    f(x) = sigmoid(x[0] + x[1]) + 0.1 * (x[0]**3 - x[1]**2) + 0.05 * (x[0] * x[1])

    Where:
        sigmoid(z) = 1 / (1 + exp(-z))
    """
    def sigmoid(z):
        return 1 / (1 + np.exp(-z))

    return sigmoid(x[0] + x[1]) + 0.1 * (x[0]**3 - x[1]**2) + 0.05 * (x[0] * x[1])

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function designed to exhibit specific ELA features. This function combines a modified Rosenbrock-like term,
    a linear term with a specific direction, and a skew-inducing term based on a shifted coordinate. Additionally, it adds a radially decreasing term centered on (0, 0) for controlled fitness std.

    Formula:
    f(x) = rosenbrock_like(x) + linear_term(x) + skew_term(x) + radial_term(x)

    Where:
    - rosenbrock_like(x) = (1-x[0])**2 + 100*(x[1] - x[0]**2)**2 * 0.001  # Scaled Rosenbrock-like term for quadratic characteristics
    - linear_term(x) = 0.1 * (x[0] - x[1])    # Linear term creating a directional bias
    - skew_term(x) = 0.05 * (x[0] - 1)**3      # Cubic term to introduce skewness, shifted
    - radial_term(x) = -0.01 * np.exp(-(x[0]**2 + x[1]**2)) # Gaussian-like function decaying from (0,0)
    """
    def rosenbrock_like(x):
        return (1-x[0])**2 + 100*(x[1] - x[0]**2)**2 * 0.001

    def linear_term(x):
        return 0.1 * (x[0] - x[1])

    def skew_term(x):
        return 0.05 * (x[0] - 1)**3

    def radial_term(x):
        return -0.01 * np.exp(-(x[0]**2 + x[1]**2))


    return rosenbrock_like(x) + linear_term(x) + skew_term(x) + radial_term(x)
